  for(const point of acPoints){const time=point.date.getTime();if(seen.has(time))continue;seen.add(time);if(!pvByTime.has(time))continue;matched++;const ac=Math.max(0,Number(point.value)||0),pv=Math.max(0,Number(pvByTime.get(time))||0),key=hourStamp(point.date),row=hours.get(key)||{time:key,load:0,pvBase:0,hours:0};row.load+=ac;row.pvBase+=pv;row.hours+=intervalHours;hours.set(key,row);observedHours+=intervalHours;peakKw=Math.max(peakKw,ac/intervalHours)}
