  const coverage=clamp(observedHours/(spanDays*24),0,1),annualFactor=YEAR_HOURS/observedHours;
  return {hours:[...hours.values()].sort((a,b)=>a.time-b.time),peakKw,spanDays,coverage,annualFactor,matched,observedHours};
