  const run=(initial,measure)=>{let soc=initial,grid=0,charged=0,discharged=0,minSoc=capacity;for(const row of rows){const charge=Math.min(row.surplus,chargeKw*row.hours,(capacity-soc)/chargeEff);soc+=charge*chargeEff;const delivered=Math.min(row.grid,dischargeKw*row.hours,soc*dischargeEff);soc-=delivered/dischargeEff;grid+=row.grid-delivered;charged+=charge;discharged+=delivered;minSoc=Math.min(minSoc,soc)}return {soc,grid,charged,discharged,minSoc}};
