  let c1=makeRow('C1','C1 · Respaldo protegido',0,0,empty,false,'Sin excedente FV evaluable',backupBefore),c2=makeRow('C2','C2 · Baterías existentes',0,0,empty,false,'Sin excedente FV evaluable',backupBefore);
  if(nArea>nA&&dcCoversPeak&&Number.isFinite(reserveCount)&&packUsable>0){const step=Math.max(1,Math.ceil((nArea-nA)/70)),candidates=[];for(let n=nA+1;n<=nArea;n+=step)candidates.push(n);if(candidates.at(-1)!==nArea)candidates.push(nArea);
   let chosen=null;for(const n of candidates){const solar=directSeries(hours,n,panelKwp,pvReferenceKwp,dcLimit);if(solar.surplus<=0)continue;const dailySurplus=solar.surplus/(series.observedHours/24),maxPacks=Math.min(16,Math.max(1,Math.ceil(dailySurplus*config.chargeEff/packUsable)+1));for(let packs=1;packs<=maxPacks;packs++){const sim=dispatch(solar.rows,packs,packUsable,config.chargeEff,config.dischargeEff,config.chargeKw,config.dischargeKw,false),backup=(existing+reserveNew)*packUsable*config.dischargeEff/siteLoadKw,row=makeRow('C1','C1 · Respaldo protegido',n,reserveNew+packs,sim,true,`Reserva de ${config.reserveHours} h protegida; ${packs} batería(s) adicionales para ahorro`,backup,sim.discharged,sim.charged),score=row.payback??Infinity;if(!chosen||score<chosen.score-1e-9||score===chosen.score&&row.capex<chosen.row.capex)chosen={n,solar,row,score}}}
   if(chosen){c1=chosen.row;const sim2=dispatch(chosen.solar.rows,existing,packUsable,config.chargeEff,config.dischargeEff,config.chargeKw,config.dischargeKw,true),backup2=siteLoadKw>0?sim2.minSoc*config.dischargeEff/siteLoadKw:0;c2=makeRow('C2','C2 · Baterías existentes',chosen.n,0,sim2,existing>0,existing>0?'Sin baterías nuevas; autonomía variable':'No hay baterías existentes',backup2,sim2.discharged,sim2.charged);if(backup2<config.reserveHours)warnings.push(`C2 reduce el respaldo mínimo simulado de ${backupBefore.toFixed(1)} h a ${backup2.toFixed(1)} h; no conserva la meta de ${config.reserveHours} h.`)}}
  const rows=[a,b,c1,c2],keepsReserve=row=>row.key!=='C2'||row.backupHours>=config.reserveHours,qualified=rows.filter(row=>row.meetsPayback&&keepsReserve(row)).sort((x,y)=>x.payback-y.payback),feasible=rows.filter(row=>row.feasible&&row.payback!==null&&keepsReserve(row)).sort((x,y)=>x.payback-y.payback),recommended=qualified[0]||null;
  if(!costReady)warnings.push('Complete costo por panel, convertidor, otros costos y operación anual para calcular el retorno.');
