 function validate(c){if(!(c.areaM2>0&&c.panelAreaM2>0&&c.panelWp>0&&c.designFactor>0&&c.designFactor<=1))throw new Error('Ingrese área útil, área por panel, potencia del panel y factor de diseño válidos.');if(!(c.batteryKwh>0&&c.siteLoadKw>0&&c.dod>0&&c.dod<=1&&c.chargeEff>0&&c.chargeEff<=1&&c.dischargeEff>0&&c.dischargeEff<=1&&c.chargeKw>0&&c.dischargeKw>0))throw new Error('Ingrese carga del sitio, capacidad de batería y parámetros de carga y descarga válidos.');if(!(c.pvReferenceKwp>0&&c.energyRate>0))throw new Error('Ingrese la potencia FV de referencia y el precio de energía BT5B del recibo.');for(const key of ['panelCost','batteryCost','converterCost','otherCapex','annualOpex'])if(c[key]!==null&&c[key]<0)throw new Error('Los costos no pueden ser negativos.');if(c.dcLimitKw!==null&&c.dcLimitKw<=0)throw new Error('El límite DC debe ser positivo o quedar vacío.')}
 const fmt=value=>Number(value).toLocaleString('es-PE',{maximumFractionDigits:2,minimumFractionDigits:2}),cash=value=>value===null?'—':`S/ ${fmt(value)}`,esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
